import axios from 'axios';
import withNavigation from "../utils/withNavigation";

const axiosInstance = axios.create({
    baseURL: 'http://localhost:5000/api',
    withCredentials: true,
});

axiosInstance.interceptors.request.use(
    async (config) => {
        const token = localStorage.getItem('token');
        if (token) {
            config.headers['Authorization'] = `Bearer ${token}`;
        }
        return config;
    },
    (error) => Promise.reject(error)
);

axiosInstance.interceptors.response.use(
    (response) => response,
    async (error) => {
        // Если ошибка 403 и токен недействителен
        if (error.response?.status === 403 && !error.config._retry) {
            error.config._retry = true;

            try {
                // Пытаемся обновить токен
                const { data } = await axiosInstance.post('/auth/refresh-token', null);
                localStorage.setItem('token', data.accessToken);
                error.config.headers['Authorization'] = `Bearer ${data.accessToken}`;
                return axiosInstance(error.config); // Повторяем запрос
            } catch (refreshError) {
                console.error('Ошибка при обновлении токена:', refreshError.response?.data?.message || refreshError.message);

                // Если обновление токена тоже вернуло 403
                if (refreshError.response?.status === 403) {
                    localStorage.clear(); // Удаляем все данные
                    this.props.navigate("/"); // Перенаправляем на страницу входа
                }

                return Promise.reject(refreshError); // Прокидываем ошибку дальше
            }
        }

        return Promise.reject(error); // Прокидываем остальные ошибки
    }
);

export default axiosInstance;
